# ---------------------------------------------------------------------------
# Leaf content: text, entities, character references, CDATA, comments, PI.
# ---------------------------------------------------------------------------


@st.composite
def _plain_chars(draw, n, exclude):
    charset = [c for c in _SAFE_ASCII if c not in exclude]
    if n <= 0:
        return ""
    chars = draw(st.lists(st.sampled_from(charset), min_size=n, max_size=n))
    return "".join(chars)


@st.composite
def _text_of_len(draw, n):
    if n == 0:
        return ""
    style = draw(
        st.sampled_from(["mixed"] * 5 + ["whitespace"] * 2 + ["unicode"] * 2 + ["control"])
    )
    if style == "whitespace":
        chars = draw(st.lists(st.sampled_from(_WS_CHARS), min_size=n, max_size=n))
        return "".join(chars)
    if style == "unicode":
        chars = draw(
            st.lists(
                st.one_of(st.sampled_from(_TEXT_SAFE), _nonascii_continuation),
                min_size=n,
                max_size=n,
            )
        )
        return "".join(chars)
    if style == "control":
        pos = draw(st.integers(min_value=0, max_value=n - 1))
        c = draw(st.sampled_from([chr(x) for x in [1, 2, 7, 8, 11, 12, 14, 27, 0]]))
        chars = draw(st.lists(st.sampled_from(_TEXT_SAFE), min_size=n - 1, max_size=n - 1))
        return "".join(chars[:pos]) + c + "".join(chars[pos:])
    chars = draw(st.lists(st.sampled_from(_TEXT_SAFE), min_size=n, max_size=n))
    return "".join(chars)


@st.composite
def _text_run(draw):
    n = draw(st.sampled_from(CONTENT_LENS))
    return draw(_text_of_len(n))


@st.composite
def _cdata_body(draw, n):
    chars = draw(st.lists(st.sampled_from(_SAFE_ASCII), min_size=n, max_size=n))
    body = "".join(chars)
    return body.replace("]]>", "]] >")


@st.composite
def _cdata(draw, well_formed=True):
    n = draw(st.sampled_from(CONTENT_LENS))
    body = draw(_cdata_body(n))
    if well_formed:
        return "<![CDATA[" + body + "]]>"
    return "<![CDATA[" + body


@st.composite
def _comment(draw, well_formed=True):
    n = draw(st.sampled_from(CONTENT_LENS))
    charset = [c for c in _SAFE_ASCII if c != "-"]
    chars = draw(st.lists(st.sampled_from(charset), min_size=n, max_size=n))
    body = "".join(chars)
    if well_formed:
        return "<!--" + body + "-->"
    return "<!--" + body


@st.composite
def _pi(draw):
    target = draw(make_name([1, 2, 3, 4, 5, 6, 8, 10, 16, 32]))
    n = draw(st.sampled_from(CONTENT_LENS[:20]))
    body = draw(_plain_chars(n, "?"))
    return "<?" + target + (" " + body if body else "") + "?>"


@st.composite
def _charref(draw):
    value = draw(st.sampled_from(CHARREF_VALUES))
    form = draw(st.sampled_from(["dec", "hex_lower", "hex_upper"]))
    if form == "dec":
        return "&#" + str(value) + ";"
    if form == "hex_lower":
        return "&#x" + format(value, "x") + ";"
    return "&#x" + format(value, "X") + ";"


@st.composite
def _reference(draw):
    return draw(
        st.one_of(st.sampled_from(["&amp;", "&lt;", "&gt;", "&quot;"]), _charref())
    )


@st.composite
def _entity_name_sweep(draw):
    mode = draw(st.sampled_from(["near_named"] * 2 + ["random_len"] * 3 + ["apos"]))
    if mode == "apos":
        return "&apos;"
    if mode == "near_named":
        base = draw(st.sampled_from(["amp", "lt", "gt", "quot"]))
        variant = draw(st.sampled_from(["prefix", "suffix", "case", "truncate"]))
        if variant == "prefix":
            name = "x" + base
        elif variant == "suffix":
            name = base + "x"
        elif variant == "case":
            name = base.upper()
        else:
            name = base[:-1] if len(base) > 1 else base
        return "&" + name + ";"
    n = draw(st.sampled_from(ENTITY_NAME_LENS))
    name = draw(_name_chars_of_len(n))
    return "&" + name + ";"


# ---------------------------------------------------------------------------
# Attributes.
# ---------------------------------------------------------------------------


@st.composite
def _text_excluding(draw, n, exclude):
    mode = draw(st.sampled_from(["plain"] * 6 + ["mostly_refs"] * 2 + ["one_defect"] * 2))
    if mode == "mostly_refs" and n > 0:
        parts = []
        total = 0
        while total < n:
            ref = draw(
                st.one_of(st.sampled_from(["&amp;", "&lt;", "&gt;", "&quot;"]), _charref())
            )
            parts.append(ref)
            total += len(ref)
        return "".join(parts)
    if mode == "one_defect" and n > 0:
        pos = draw(st.integers(min_value=0, max_value=n - 1))
        prefix = draw(_plain_chars(pos, exclude))
        defect = draw(
            st.one_of(
                _truncated_utf8_seq_strategy(),
                st.just(_raw_byte(0x80)),
                st.just("\x00"),
                st.sampled_from(_OVERLONG_SEQS),
            )
        )
        suffix = draw(_plain_chars(max(n - pos - 1, 0), exclude))
        return prefix + defect + suffix
    return draw(_plain_chars(n, exclude))


@st.composite
def _unquoted_text(draw, n):
    if n == 0:
        return ""
    chars = draw(st.lists(st.sampled_from(_UNQUOTED_SAFE), min_size=n, max_size=n))
    return "".join(chars)


@st.composite
def _attr_value(draw):
    n = draw(st.sampled_from(ATTR_VALUE_LENS))
    style = draw(st.sampled_from(["dquote"] * 5 + ["squote"] * 3 + ["unquoted"] * 2))
    if style == "dquote":
        body = draw(_text_excluding(n, "<\""))
        return '"' + body + '"'
    if style == "squote":
        body = draw(_text_excluding(n, "<'"))
        return "'" + body + "'"
    body = draw(_unquoted_text(n))
    return body


@st.composite
def _attribute(draw):
    name = draw(make_name(NAME_LENS))
    value = draw(_attr_value())
    eq = draw(st.sampled_from(["=", "=", "= ", " =", "=\n"]))
    return name + eq + value


@st.composite
def _attribute_list(draw):
    count = draw(st.sampled_from(ATTR_COUNT_LENS))
    attrs = draw(st.lists(_attribute(), min_size=count, max_size=count))
    add_dup = draw(st.sampled_from([False] * 5 + [True] * 2))
    if add_dup:
        dup_name = draw(make_name(NAME_LENS[1:100]))
        v1 = draw(_attr_value())
        v2 = draw(_attr_value())
        attrs = attrs + [dup_name + "=" + v1, dup_name + "=" + v2]
    return "".join(" " + a for a in attrs)


# ---------------------------------------------------------------------------
# Recursive element/content tree with matched tag names.
# ---------------------------------------------------------------------------


@st.composite
def _leaf_content(draw):
    return draw(
        st.one_of(_text_run(), _reference(), _cdata(True), _comment(True), _pi())
    )


@st.composite
def _element_with_children(draw, children):
    name = draw(make_name(NAME_LENS))
    attrs = draw(_attribute_list())
    kind = draw(
        st.sampled_from(
            ["paired"] * 6 + ["selfclose"] * 3 + ["mismatched"] + ["empty_name_pair"]
        )
    )
    if kind == "empty_name_pair":
        name = ""
    if kind == "selfclose":
        return "<" + name + attrs + "/>"
    n_children = draw(
        st.sampled_from([0, 0, 0, 1, 1, 2, 3, 4, 5, 6, 8, 10, 16, 24, 32])
    )
    kids = draw(st.lists(children, min_size=n_children, max_size=n_children))
    body = "".join(kids)
    if kind == "mismatched":
        close_name = draw(_mismatch_name(name))
        return "<" + name + attrs + ">" + body + "</" + close_name + ">"
    return "<" + name + attrs + ">" + body + "</" + name + ">"


content_strategy = st.recursive(
    _leaf_content(), lambda ch: _element_with_children(ch), max_leaves=40
)


# ---------------------------------------------------------------------------
# Deep nesting chain (matched names threaded via a loop, not Python
# recursion, so depth can go into the thousands without hitting the
# interpreter's call-stack limit). Depth is always drawn from a Hypothesis
# strategy, so it varies and shrinks.
# ---------------------------------------------------------------------------


@st.composite
def _deep_chain_core(draw, depth, leaf):
    vary_names = draw(st.booleans()) and depth <= 64
    names = []
    for _ in range(depth):
        if vary_names:
            names.append(draw(make_name([1, 2, 3, 4, 5, 6, 8])))
        else:
            names.append("a")
    opens = "".join("<" + nm + ">" for nm in names)
    closes = "".join("</" + nm + ">" for nm in reversed(names))
    return opens + leaf + closes


_NEAR_MISS_LEAF_KINDS = [
    "unsupported_entity", "unterminated_comment", "unterminated_cdata",
    "control_char", "bad_charref", "dup_attr_leaf",
]


@st.composite
def _leaf_defect_payload(draw):
    kind = draw(st.sampled_from(_NEAR_MISS_LEAF_KINDS))
    if kind == "unsupported_entity":
        return draw(_entity_name_sweep())
    if kind == "unterminated_comment":
        n = draw(st.sampled_from(CONTENT_LENS[:20]))
        return "<!--" + draw(_plain_chars(n, "-"))
    if kind == "unterminated_cdata":
        n = draw(st.sampled_from(CONTENT_LENS[:20]))
        return "<![CDATA[" + draw(_plain_chars(n, ""))
    if kind == "control_char":
        c = draw(st.sampled_from([chr(x) for x in [1, 2, 7, 8, 11, 12, 14, 27]]))
        return draw(_text_run()) + c + draw(_text_run())
    if kind == "bad_charref":
        v = draw(st.sampled_from([0, 0xD800, 0xDFFF, 0x110000, 0xFFFFFFFF]))
        form = draw(st.sampled_from(["dec", "hex"]))
        return ("&#%d;" % v) if form == "dec" else ("&#x%x;" % v)
    aname = draw(make_name([1, 2, 3, 4]))
    val = draw(_attr_value())
    return "<z " + aname + "=" + val + " " + aname + "=" + val + "/>"


# ---------------------------------------------------------------------------
# Prolog and misc.
# ---------------------------------------------------------------------------


@st.composite
def _prolog(draw):
    realistic = draw(st.booleans())
    if realistic:
        ver = draw(st.sampled_from(['"1.0"', "'1.0'", '"1.1"']))
        attrs = " version=" + ver
    else:
        attrs = draw(st.one_of(st.just(""), _attribute_list()))
    has_space = True if attrs != "" else draw(st.booleans())
    return "<?xml" + (" " if has_space else "") + attrs + "?>"


@st.composite
def _misc(draw):
    return draw(
        st.one_of(_comment(True), _pi(), st.sampled_from([" ", "\n", "\t", "  \n\t "]))
    )


@st.composite
def _misc_list(draw, max_n=4):
    n = draw(st.integers(min_value=0, max_value=max_n))
    parts = draw(st.lists(_misc(), min_size=n, max_size=n))
    return "".join(parts)


# ---------------------------------------------------------------------------
# Well-formed top-level documents.
