@st.composite
def _full_document(draw):
    pre = draw(st.one_of(st.just(""), _prolog()))
    pre_misc = draw(_misc_list(4))
    root = draw(_element_with_children(content_strategy))
    post_misc = draw(_misc_list(4))
    return pre + pre_misc + root + post_misc


@st.composite
def _rootless_document(draw):
    return draw(_misc_list(6))


@st.composite
def _deep_well_formed_document(draw):
    depth = draw(st.sampled_from(DEPTH_LENS))
    leaf = draw(
        st.one_of(_text_run(), _reference(), _cdata(True), _comment(True), _pi(), st.just(""))
    )
    core = draw(_deep_chain_core(depth, leaf))
    pre = draw(st.one_of(st.just(""), _prolog()))
    pre_misc = draw(_misc_list(3))
    post_misc = draw(_misc_list(3))
    return pre + pre_misc + core + post_misc


@st.composite
def _attr_boundary_document(draw):
    name = draw(make_name(NAME_LENS))
    attrs = draw(_attribute_list())
    self_close = draw(st.booleans())
    if self_close or name == "":
        return "<" + name + attrs + "/>"
    body = draw(st.one_of(_text_run(), st.just("")))
    return "<" + name + attrs + ">" + body + "</" + name + ">"


@st.composite
def _doctype_document(draw):
    root_name = draw(make_name([1, 2, 3, 4, 5, 8]))
    variant = draw(st.sampled_from(["simple", "internal_subset"]))
    if variant == "simple":
        doctype = "<!DOCTYPE " + root_name + ">"
    else:
        doctype = "<!DOCTYPE " + root_name + " [<!ELEMENT " + root_name + " EMPTY>]>"
    body = draw(st.one_of(_text_run(), st.just("")))
    if body == "":
        return doctype + "<" + root_name + "/>"
    return doctype + "<" + root_name + ">" + body + "</" + root_name + ">"


@st.composite
def _empty_name_document(draw):
    kind = draw(st.sampled_from(["selfclose", "paired"]))
    if kind == "selfclose":
        return "< />"
    body = draw(st.one_of(_text_run(), st.just("")))
    return "< >" + body + "</ >"


@st.composite
def _nonascii_name_document(draw):
    n = draw(st.sampled_from(NAME_LENS[1:60]))
    first = draw(_name_start_char("nonascii"))
    rest = draw(st.lists(_name_char("mixed"), min_size=n - 1, max_size=n - 1)) if n > 1 else []
    name = first + "".join(rest)
    attrs = draw(_attribute_list())
    return "<" + name + attrs + "/>"


@st.composite
def _many_long_attrs_document(draw):
    count, value_len = draw(st.sampled_from(_COMBO_COUNT_LEN_PAIRS))
    name = draw(make_name([1, 2, 3, 4, 5]))
    parts = []
    for _ in range(count):
        aname = draw(make_name([1, 2, 3, 4, 5, 6]))
        body = draw(_plain_chars(value_len, "<\""))
        parts.append(" " + aname + '="' + body + '"')
    return "<" + name + "".join(parts) + "/>"


@st.composite
def _deep_long_name_document(draw):
    depth, namelen = draw(st.sampled_from(_COMBO_DEPTH_NAMELEN_PAIRS))
    name = draw(make_name([namelen]))
    leaf = draw(_text_run())
    return ("<" + name + ">") * depth + leaf + ("</" + name + ">") * depth


