@st.composite
def _multiple_roots_document(draw):
    e1 = draw(_element_with_children(content_strategy))
    e2 = draw(_element_with_children(content_strategy))
    ws = draw(st.sampled_from(["", " ", "\n"]))
    return e1 + ws + e2


@st.composite
def _mismatched_top_document(draw):
    name = draw(make_name(NAME_LENS[:80]))
    attrs = draw(_attribute_list())
    body = draw(st.one_of(_text_run(), st.just("")))
    close_name = draw(_mismatch_name(name))
    return "<" + name + attrs + ">" + body + "</" + close_name + ">"


@st.composite
def _bad_attribute_document(draw):
    name = draw(make_name([1, 2, 3, 4, 5, 8, 16]))
    kind = draw(st.sampled_from(["missing_eq", "missing_value", "unterminated_value", "dup_attr_only"]))
    aname = draw(make_name([1, 2, 3, 4, 5, 8]))
    if kind == "missing_eq":
        tag_attrs = " " + aname + '"x"'
    elif kind == "missing_value":
        tag_attrs = " " + aname + "="
    elif kind == "unterminated_value":
        n = draw(st.sampled_from(CONTENT_LENS[:15]))
        val_body = draw(_plain_chars(n, "<\""))
        tag_attrs = " " + aname + '="' + val_body
    else:
        val = draw(_attr_value())
        tag_attrs = " " + aname + "=" + val + " " + aname + "=" + val
    return "<" + name + tag_attrs + "/>"


@st.composite
def _unsupported_entity_document(draw):
    depth = draw(st.sampled_from(DEPTH_LENS[:40]))
    entity = draw(_entity_name_sweep())
    return draw(_deep_chain_core(depth, entity))


@st.composite
def _deep_defect_document(draw):
    depth = draw(st.sampled_from(DEPTH_LENS))
    leaf = draw(_leaf_defect_payload())
    core = draw(_deep_chain_core(depth, leaf))
    pre = draw(st.one_of(st.just(""), _prolog()))
