def _cap_size(s):
    limit = 60000
    if len(s) <= limit:
        return s
    return s[:limit]


def documents():
    well_formed = (
        [_full_document()] * 7
        + [_rootless_document()] * 1
        + [_deep_well_formed_document()] * 5
        + [_attr_boundary_document()] * 3
        + [_doctype_document()] * 2
        + [_empty_name_document()] * 1
        + [_nonascii_name_document()] * 1
        + [_many_long_attrs_document()] * 2
        + [_deep_long_name_document()] * 2
    )
    near_miss = (
        [_multiple_roots_document()] * 2
        + [_mismatched_top_document()] * 2
        + [_bad_attribute_document()] * 2
        + [_unsupported_entity_document()] * 2
        + [_deep_defect_document()] * 3
